function panelKey(filename) { return path.resolve(filename).toLowerCase(); }

function nonce() { return [...Array(32)].map(() => Math.floor(Math.random() * 36).toString(36)).join(''); }
function hostCapabilities() { return detectCapabilities({ uiKind: vscode.env.uiKind === vscode.UIKind.Web ? 'web' : 'desktop', platform: process.platform, environment: process.env }); }
function escapeHtml(value) { return String(value || '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char])); }
function profileFor(filename) { const found = soundProfile.locate(filename); if (!found) return null; try { return soundProfile.read(found); } catch (error) { return { filename: found, root: path.dirname(found), profile: null, errors: [error.message], warnings: [] }; } }
function eventName(profile, entry) { const found = profile && soundProfile.eventMap(profile).get(entry.identity); return found ? found.name || found.id || entry.identity : '' ; }
function archiveDefinition(profileRecord, filename) { if (!profileRecord || !profileRecord.profile) return null; return (profileRecord.profile.archives || []).map((entry) => soundProfile.resolveArchive(profileRecord.root, entry)).find((entry) => path.resolve(entry.sndPath).toLowerCase() === path.resolve(filename).toLowerCase()) || null; }
function manifestFor(definition) { if (!definition) throw new Error('Assign this SND to an archive in its sound profile first.'); if (!definition.buildManifestPath) throw new Error(`Archive ${definition.id} has no buildManifest path. Add one to the sound profile.`); if (!fs.existsSync(definition.buildManifestPath)) throw new Error(`Build manifest does not exist: ${definition.buildManifestPath}`); return definition.buildManifestPath; }
function characterRoot(filename) { let current = path.dirname(path.resolve(filename)); while (true) { try { if (fs.readdirSync(current).some((name) => /\.def$/i.test(name))) return current; } catch (_) {} const parent = path.dirname(current); if (parent === current) return path.dirname(filename); current = parent; } }
function mutationOptions(filename, label, overrides = {}) { const resource = vscode.Uri.file(filename), legacy = vscode.workspace.getConfiguration('ikemenZss', resource).get('sndCreateBackups', true); return optionsFromConfig(vscode, filename, label, { journalRoot: characterRoot(filename), backup: false, ...overrides }); }

function referenceReport(root, profile) {
  const prefixes = (profile.archives || []).map((item) => soundProfile.cleanId(item.prefix)).filter(Boolean), findings = [], extensions = new Set(['.zss', '.cns', '.inp', '.cmd', '.jnp', '.def']);
  const visit = (directory) => { for (const entry of fs.readdirSync(directory, { withFileTypes: true })) { if (entry.name.startsWith('.') || /^(?:backup|backups)$/i.test(entry.name)) continue; const full = path.join(directory, entry.name); if (entry.isDirectory()) visit(full); else if (extensions.has(path.extname(entry.name).toLowerCase())) { const lines = fs.readFileSync(full, 'utf8').split(/\r?\n/); lines.forEach((line, index) => { if (!/(?:playSnd|hitSound|guardSound)/i.test(line)) return; const prefix = prefixes.find((item) => new RegExp(`\\b${item}\\s*-?\\d`, 'i').test(line)) || (/\bS\s*-?\d/i.test(line) ? 'S' : 'unprefixed'); findings.push({ file: full, line: index + 1, prefix, text: line.trim() }); }); } } };
  visit(root); return findings;
}

function clientModel(archive, profileRecord, experience = workspaceExperience('snd', 'learning')) {
  const definition = archiveDefinition(profileRecord, archive.filename), groups = new Map();
  const entries = archive.entries.map((entry) => { const item = { archiveIndex: entry.archiveIndex, group: entry.group, index: entry.index, identity: entry.identity, duplicateOf: entry.duplicateOf, dataSize: entry.dataSize, name: eventName(profileRecord && profileRecord.profile, entry), category: soundCategory(entry), ...entry.wav }; if (!groups.has(entry.group)) groups.set(entry.group, 0); groups.set(entry.group, groups.get(entry.group) + 1); return item; });
  return { filename: archive.filename, basename: path.basename(archive.filename), version: archive.version.join('.'), declaredCount: archive.declaredCount, entries, groups: [...groups].map(([group, count]) => ({ group, count })), issues: archive.issues, capabilities: hostCapabilities(), mutation: policyFromConfig(vscode, archive.filename), experience, profile: profileRecord && profileRecord.profile ? { filename: profileRecord.filename, displayFilename: path.basename(profileRecord.filename), characterId: profileRecord.profile.characterId, definition, validation: { errors: profileRecord.errors || [], warnings: profileRecord.warnings || [] } } : { filename: profileRecord && profileRecord.filename || null, validation: { errors: profileRecord && profileRecord.errors || [], warnings: [] } } };
}

